int ring_buffer_map_vma_open(struct trace_buffer *buffer, int cpu)
{
	struct ring_buffer_per_cpu *cpu_buffer;

	if (!cpumask_test_cpu(cpu, buffer->cpumask))
		return -EINVAL;

	cpu_buffer = buffer->buffers[cpu];

	guard(mutex)(&cpu_buffer->mapping_lock);

	if (!cpu_buffer->user_mapped)
		return -ENODEV;

	return __rb_inc_dec_mapped(cpu_buffer, true);
}
EXPORT_SYMBOL_GPL(ring_buffer_map_vma_open);

